import type {Category} from '../core/types';

/** one entry of catalog.json (generated by cli/gen-registry.mjs) */
export interface CatalogEntry {
  id: string;
  title: string;
  category: Category;
  description: string;
  useFor: string;
  source: string[];
  durationInFrames: number;
  tags: string[];
  /** source file, relative to the library root */
  file: string;
  /** can render on a transparent background (merge `overlayProps`) */
  overlay: boolean;
  overlayProps: Record<string, unknown> | null;
  takesImage: boolean;
  imageProps: string[];
  takesText: boolean;
  textProps: string[];
  colorProps: string[];
  /** last frame flows into the first (seamless loop) */
  loopable: boolean;
  loopProps?: Record<string, unknown>;
  bestLength: number;
  /** dark | mid | light + looks: paper neon blueprint photo 3d pixel comic cinematic nature hud playful editorial ui night */
  mood: string[];
  /** how it is used in a mix: backdrop | subject | type | accent | frame | transition | mix */
  roles: string[];
  /** render cost in a browser: light (SVG) | medium (image filters) | heavy (three.js / WebGL) */
  weight: 'light' | 'medium' | 'heavy';
  formats: ('landscape' | 'square' | 'portrait')[];
  pairsWith: string[];
  notes?: string;
  avoid?: string;
  props: Record<string, {default: unknown; doc: string}>;
}
